=5}},order={{l1=10,l2=14,tree="BM",name=S[339],r1=1,r2=5,max=5},{l1=15,l2=16,tree="BM",name=S[666],r1=1,r2=2,max=2},{l1=17,l2=18,tree="BM",name=S[507],r1=1,r2=2,max=2},{l1=19,l2=19,tree="BM",name=S[530],r1=1,r2=1,max=5},{l1=20,l2=20,tree="BM",name=S[559],r1=1,r2=1,max=1},{l1=21,l2=22,tree="BM",name="Pathfinding",r1=1,r2=2,max=2},{l1=23,l2=24,tree="BM",name=S[453],r1=1,r2=2,max=5},{l1=25,l2=25,tree="BM",name="Summon Hawk",r1=1,r2=1,max=1},{l1=26,l2=29,tree="BM",name="Ferocity",r1=1,r2=4,max=5},{l1=30,l2=30,tree="BM",name=S[531],r1=1,r2=1,max=1},{l1=31,l2=31,tree="BM",name="Ferocity",r1=5,r2=5,max=5},{l1=32,l2=34,tree="BM",name=S[453],r1=3,r2=5,max=5},{l1=35,l2=39,tree="BM",name="Frenzy",r1=1,r2=5,max=5},{l1=40,l2=40,tree="BM",name=S[483],r1=1,r2=1,max=1},{l1=41,l2=43,tree="MM",name="Hawk Eye",r1=1,r2=3,max=3},{l1=44,l2=45,tree="MM",name=S[210],r1=1,r2=2,max=5},{l1=46,l2=50,tree="MM",name="Careful Aim",r1=1,r2=5,max=5},{l1=51,l2=52,tree="MM",name=S[365],r1=1,r2=2,max=2},{l1=53,l2=55,tree="MM",name=S[210],r1=3,r2=5,max=5},{l1=56,l2=56,tree="MM",name=S[366],r1=1,r2=1,max=1},{l1=57,l2=60,tree="MM",name=S[409],r1=1,r2=4,max=5}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[277]},{t="p",s="legend",x="|cff71d5ffBlue text was updated for the WoW Forever hotfixes up to 10 November and is awaiting final review.|r"},{t="h1",x=S[644],sub=S[353]},{t="p",s="lede",x="Single-target PvE Beast Mastery: your pet and two hawks carry the damage while Deadly Aspects, Frenzy and Bestial Wrath keep the whole team fast, backed by Marksmanship crit and Trueshot Aura. Not built for PvP or AoE farming."},{t="pills",list={S[281],S[189],S[317]}},{t="anchor",id="journey"},{t="kicker",x=S[484]},{t="h2",x=S[214]},{t="p",x=S[49]},{t="p",s="level",x="1–19 · Pet foundations"},{t="p",x="Use ranged openings, train your pet at 10, and establish pet threat before spending mana. Deadly Aspects reaches 5/5 by level 14, Focused Fire 2/2 by 16, Improved Revive Pet 2/2 by 18 and Endurance Training 1/5 at 19. Fight one enemy at a time and keep pet food, ammunition and learned abilities current."},{t="p",s="level",x="20–39 · Hawks and pet damage"},{t="p",x="Bestial Swiftness arrives at 20 and Pathfinding is 2/2 by 22. Unleashed Fury is 2/5 by 24, Summon Hawk arrives at 25, Ferocity is 4/5 by 29, Intimidation arrives at 30, Ferocity finishes at 31 and Unleashed Fury at 34, and Frenzy is 5/5 by 39. Frenzy needs 25 points in Beast Mastery and a full Ferocity, so do not spend it earlier."},{t="p",s="level",x="40–60 · Marksmanship support"},{t="p",x="Bestial Wrath at 40 completes the 31-point Beast Mastery tree. The last twenty points go into Marksmanship: Hawk Eye 3/3 (41–43) for range, Lethal Attacks 5/5 (44–45 and 53–55) for crit, Careful Aim 5/5 (46–50), Rapid Killing 2/2 (51–52), Trueshot Aura at 56 for your party’s ranged attack power, and Mortal Shots 4/5 (57–60) for bigger ranged crits."},{t="anchor",id="talents"},{t="kicker",x=S[248]},{t="h2",x=S[281]},{t="p",x="Tree order: Beast Mastery / Marksmanship / Survival. These 51 points are entered on the Standards.gg talent calculator and checked against the launch talent trees for totals, maximum ranks, tier gates and prerequisites. Changes made inside the calculator do not rewrite this guide."},{t="widget",w="talents"},{t="h4",s="summary",x=S[286]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[233]},{t="p",x="Spend one point per level in each range. Unlisted talents stay at zero. This order has been checked for totals, maximum ranks, tier gates and prerequisites."},{t="widget",w="order"},{t="p",s="notice",x="|cffffffffBuilt for single-target PvE.|r This allocation is tuned for one enemy at a time: questing elites, dungeon bosses and raid-style boss fights. It is not a PvP build and not an area-damage (AoE) farming build; it takes no Scatter Shot, Deterrence, Entrapment or Barrage, and the damage comes from your pet, hawks and a steady single-target shot rotation."},{t="p",s="notice",x="Trueshot Aura raises ranged attack power for your whole party, and Careful Aim turns your Intellect into attack power, so Intellect on gear is worth a little more in this build."},{t="anchor",id="stats"},{t="kicker",x=S[354]},{t="h2",x=S[264]},{t="p",x="Your ranged weapon is your biggest upgrade. After that, Agility and attack power raise the damage of you and your shots, and Intellect turns into attack power through Careful Aim."},{t="h3",x=S[454]},{t="stat",i=1,b=S[471],x=""},{t="stat",i=2,b="Agility",x=S[244]},{t="stat",i=3,b="Stamina",x=""},{t="stat",i=4,b="Intellect",x=S[253]},{t="p",s="small",x="Strength only helps melee attacks, so it is a low priority. Melee weapons matter only for their Agility and attack power."},{t="h3",x="At level 60"},{t="stat",i=1,b=S[367],x=S[340]},{t="stat",i=2,b="Hit chance",x="to 8%"},{t="stat",i=3,b=S[433],x=""},{t="stat",i=4,b="Agility",x=""},{t="stat",i=5,b=S[532],x=""},{t="p",s="small",x="Some estimates put the hit target at 9%. Intellect still has value through Careful Aim and your mana pool."},{t="p",s="notice",x=S[55]},{t="anchor",id="combat"},{t="kicker",x=S[265]},{t="h2",x=S[455]},{t="p",x=S[57]},{t="h4",x="Prepare the pull"},{t="p",x="Use Aspect of the Hawk, mark the target and send your pet first. With Aspect of the Hawk active, Deadly Aspects gives Auto Shot a 10% chance to raise your ranged attack speed by 30% for 12 seconds, so keep Auto Shot running. From 56, keep Trueshot Aura active for your party."},{t="h4",x="Maintain pet and hawk uptime"},{t="p",x="Keep up to two hawks attacking durable targets (Summon Hawk keeps attacking for 18 seconds and shares its cooldown with Arcane Shot|cff71d5ff; it and Arcane Shot cost 11% of your base Mana at every rank|r). Unleashed Fury adds 15% to pet and hawk damage and Ferocity adds 10% crit, while Frenzy gives your pet a 30% attack speed boost for 8 seconds after each crit. Use Bestial Wrath (+50% pet damage for 18 seconds) when the pet can attack throughout the window."},{t="h4",x="Choose shots for one target"},{t="p",x="Use Serpent Sting when the target will survive enough ticks, and Aimed Shot as your single-target starting choice. Use Arcane Shot selectively when it will not delay useful Hawk uptime. You do not need Multi-Shot for this build; keep your attention on the target your pet is fighting."},{t="h4",x="Protect the pet and your mana"},{t="p",x="Focused Fire gives you and your pet 2% more damage while the pet is active, so a dead pet costs more than its own damage. Mend Pet early enough to prevent a death, and use Intimidation to stun the target on your pet's next attack (with +100% crit chance) for control and threat. Bestial Discipline lets 50% of your mana regeneration continue while casting. Traps and Feign Death are your emergency tools."},{t="h4",x=S[303]},{t="p",x="This build is for questing elites, dungeon bosses and boss fights, not for PvP or for farming packs. In groups, leave pack damage to others and keep your pet, hawks and shots on your boss target."},{t="abil",names={"Summon Hawk",S[483],S[531],"Aimed Shot","Arcane Shot",S[485],S[486],S[487],"Feign Death"}},{t="h3",x=S[378]},{t="p",x="Compare damage range, weapon speed, useful stats, requirements and your actual equipped item. Ranged-only bonuses do not improve melee attacks. Agility remains useful; this build also invests in Careful Aim (2/5), which turns Intellect into Attack Power, and Surefooted gives 3% hit. Do not apply a generic hit number to every encounter or attack type: check the current rules for your target and weapons before removing Surefooted."},{t="p",x=S[46]},{t="anchor",id="macros"},{t="kicker",x=S[326]},{t="h2",x=S[327]},{t="p",x=S[45]},{t="p",x=S[36]},{t="macro",n=S[208],x=S[70],code=S[154]},{t="macro",n=S[266],x=S[75],code=S[135]},{t="macro",n=S[488],x=S[67],code=S[278]},{t="macro",n=S[434],x=S[97],code=S[304]},{t="macro",n="Mend Pet",x=S[89],code=S[150]},{t="macro",n=S[225],x=S[60],code=S[102]},{t="macro",n=S[226],x=S[61],code=S[109]},{t="macro",n="Wing Clip",x=S[78],code=S[112]},{t="macro",n="Bestial Wrath and pet attack",x="Requires the selected Bestial Wrath talent and a usable pet. Sends your pet at your target as you activate the cooldown.",code="#showtooltip Bestial Wrath\n/petattack [harm,nodead]\n/cast [harm,nodead] Bestial Wrath"},{t="macro",n="Intimidation and pet attack",x="Requires Intimidation. Direct your pet at the enemy you want it to stun; do not use this on a target you intend to keep trapped.",code="#showtooltip Intimidation\n/petattack [harm,nodead]\n/cast [harm,nodead] Intimidation"},{t="anchor",id="dungeons"},{t="kicker",x=S[435]},{t="h2",x=S[234]},{t="p",x=S[42]},{t="widget",w="rarity"},{t="p",s="notice",x=S[51]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[267]},{t="h2",x=S[227]},{t="p",x=S[44]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[287]},{t="h2",x=S[215]},{t="p",x=S[40]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[268]},{t="h2",x=S[201]},{t="p",x=S[41]},{t="widget",w="quest"},{t="anchor",id=S[243]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[58]}}},{id="marksmanship",name=S[667],token="MM",title="Marksmanship | WoW Forever Hunter Field Guide",nav={{id="overview",x=S[482]},{id="journey",x=S[315]},{id="talents",x=S[247]},{id="stats",x=S[350]},{id="combat",x=S[351]},{id="macros",x=S[352]},{id="dungeons",x=S[285]},{id="professions",x=S[316]},{id="crafting",x=S[302]},{id="questgear",x=S[276]},{id=S[243],x=S[432]}},asideNote="Researched 29 October 2026\nForever data only\n\nHover, focus or tap an item icon for its tooltip. Click to keep it open; Escape closes it.\n\nMain guide: 721 words.\nReference tables and tooltips are additional.",talentString="0000000000000000005355201152305150005003",ranks={{tree="MM",name=S[210],r=5,max=5},{tree="MM",name=S[589],r=3,max=3},{tree="MM",name="Efficiency",r=5,max=5},{tree="MM",name="Careful Aim",r=5,max=5},{tree="MM",name=S[365],r=2,max=2},{tree="MM",name="Lone Wolf",r=1,max=1},{tree="MM",name=S[366],r=1,max=1},{tree="MM",name=S[409],r=5,max=5},{tree="MM",name=S[533],r=2,max=2},{tree="MM",name="Barrage",r=3,max=3},{tree="MM",name=S[341],r=5,max=5},{tree="MM",name="Sniper Shot",r=1,max=1},{tree="SV",name=S[298],r=5,max=5},{tree="SV",name="Survivalist",r=5,max=5},{tree="SV",name="Surefooted",r=3,max=3}},order={{l1=10,l2=14,tree="MM",name=S[210],r1=1,r2=5,max=5},{l1=15,l2=19,tree="MM",name="Careful Aim",r1=1,r2=5,max=5},{l1=20,l2=21,tree="MM",name=S[365],r1=1,r2=2,max=2},{l1=22,l2=24,tree="MM",name=S[589],r1=1,r2=3,max=3},{l1=25,l2=29,tree="MM",name=S[409],r1=1,r2=5,max=5},{l1=30,l2=30,tree="MM",name=S[366],r1=1,r2=1,max=1},{l1=31,l2=33,tree="MM",name="Barrage",r1=1,r2=3,max=3},{l1=34,l2=34,tree="MM",name="Lone Wolf",r1=1,r2=1,max=1},{l1=35,l2=39,tree="MM",name=S[341],r1=1,r2=5,max=5},{l1=40,l2=40,tree="MM",name="Sniper Shot",r1=1,r2=1,max=1},{l1=41,l2=45,tree="MM",name="Efficiency",r1=1,r2=5,max=5},{l1=46,l2=47,tree="MM",name=S[533],r1=1,r2=2,max=2},{l1=48,l2=52,tree="SV",name=S[298],r1=1,r2=5,max=5},{l1=53,l2=57,tree="SV",name="Survivalist",r1=1,r2=5,max=5},{l1=58,l2=60,tree="SV",name="Surefooted",r1=1,r2=3,max=3}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[277]},{t="h1",x=S[667],sub=S[353]},{t="p",s="lede",x="Single-target PvE Marksmanship: a petless ranged build that stacks Lone Wolf, Careful Aim, Mortal Shots and Ranged Weapon Specialization on one target at a time, with Survival hit and health support. Not built for PvP or AoE farming."},{t="pills",list={S[430],S[189],S[317]}},{t="anchor",id="journey"},{t="kicker",x=S[484]},{t="h2",x=S[214]},{t="p",x=S[49]},{t="p",s="level",x="1–19 · Learn the shooting core"},{t="p",x="Lethal Attacks reaches 5/5 by level 14 and Careful Aim 5/5 by 19. A pet remains useful while leveling even though the final build contains Lone Wolf, so train pet skills, maintain ammunition and use a strong ranged weapon."},{t="p",s="level",x="20–39 · Build ranged damage"},{t="p",x="Aimed Shot is trained at 20. Rapid Killing is 2/2 by 21, Improved Stings 3/3 by 24, Mortal Shots 5/5 by 29, Trueshot Aura arrives at 30 and Barrage is 3/3 by 33. Lone Wolf is taken at 34 and Ranged Weapon Specialization is 5/5 by 39. Lone Wolf only pays off without an active pet, so keep your leveling pet until you switch to petless play."},{t="p",s="level",x="40–60 · Finish Marksmanship, then Survival"},{t="p",x="Sniper Shot at 40 completes the 31-point core. The last twenty points finish Marksmanship (Efficiency 5/5 by 45, Rapid Recuperation 2/2 by 47), then add Survival support: Improved Tracking, Survivalist and Surefooted (48–60). This build has no Beast Mastery points, so there is no Deadly Aspects or pet damage package."},{t="anchor",id="talents"},{t="kicker",x=S[248]},{t="h2",x=S[430]},{t="p",x=S[64]},{t="widget",w="talents"},{t="h4",s="summary",x=S[286]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[233]},{t="p",x="Spend one point per level in each range. Unlisted talents stay at zero. This sequence has been checked against the calculator for totals, maximum ranks, tier gates and named prerequisites. After Sniper Shot at 40, the last twenty points finish Marksmanship first, then add Survival."},{t="widget",w="order"},{t="p",s="notice",x="|cffffffffBuilt for single-target PvE.|r This allocation is tuned for one enemy at a time: questing elites, dungeon bosses and raid-style boss fights. It is not a PvP build and not an area-damage (AoE) farming build; it takes no Scatter Shot, Deterrence, Entrapment or other control talents, and the damage comes from steady single-target ranged shots."},{t="p",s="notice",x="For Beast Mastery and Marksmanship, 5/5 Survivalist and 3/3 Surefooted are flexible once your character is hit capped from other sources and raids are on farm. Remove Surefooted only if you remain hit capped without its bonus; remove Survivalist only when you can comfortably give up its extra health. Reallocate the freed points to damage, mana efficiency or utility that suits your playstyle. Preserve tier requirements and prerequisites: removing Survivalist also changes access to deeper Survival talents, so recalculate the entire build rather than moving isolated points."},{t="anchor",id="stats"},{t="kicker",x=S[354]},{t="h2",x=S[264]},{t="p",x="Marksmanship lives on its ranged weapon: Aimed Shot and your other shots all scale with weapon damage. Agility and attack power come next, with Intellect adding attack power through Careful Aim."},{t="h3",x=S[454]},{t="stat",i=1,b=S[471],x=""},{t="stat",i=2,b="Agility",x=S[244]},{t="stat",i=3,b="Stamina",x=""},{t="stat",i=4,b="Intellect",x=S[253]},{t="p",s="small",x="Strength only helps melee attacks, so it is a low priority for this ranged build."},{t="h3",x="At level 60"},{t="stat",i=1,b=S[367],x=S[340]},{t="stat",i=2,b="Hit chance",x="to 8%"},{t="stat",i=3,b=S[433],x=""},{t="stat",i=4,b="Agility",x=""},{t="stat",i=5,b=S[532],x=""},{t="p",s="small",x="Some estimates put the hit target at 9%. Critical strike is the most valuable secondary stat after hit."},{t="p",s="notice",x=S[55]},{t="anchor",id="combat"},{t="kicker",x=S[265]},{t="h2",x=S[455]},{t="p",x=S[57]},{t="h4",x="Prepare the petless setup"},{t="p",x="Dismiss your pet to activate Lone Wolf, which gives you 20% increased damage with all attacks while you have no active pet. Use Aspect of the Hawk, Trueshot Aura (extra ranged attack power for your party), the appropriate tracking for Improved Tracking, mark the target and maintain Auto Shot. Solo leveling can still use a pet, with Lone Wolf inactive."},{t="h4",x="Use Aimed Shot as your main shot"},{t="p",x="Careful Aim turns 100% of your Intellect into Attack Power, Lethal Attacks adds 5% crit, Mortal Shots raises ranged critical damage by 30% and Ranged Weapon Specialization adds 5% ranged damage. Barrage adds 15% to Aimed Shot, so Aimed Shot is your single-target core. You do not need Multi-Shot for this build."},{t="h4",x="Fit Sniper Shot into safe windows"},{t="p",x="Sniper Shot has a four-second cast and a 15-second cooldown, adds bonus damage and increases the range of your next 3 Shots by 10 yards for 10 seconds. Use it where movement and mana allow a useful cast; it is not an execute. Exact endgame priority remains provisional."},{t="h4",x="Use Sting and recovery deliberately"},{t="p",x="Apply Serpent Sting on suitable targets (Improved Stings adds 20% damage). Rapid Killing raises your next Shot by 20% within 20 seconds after you kill an enemy that carries your Sting, and Rapid Recuperation lets 50% of your mana regeneration continue while casting, or 100% once Rapid Killing is consumed. Kill-triggered benefits are not repeatedly available on one isolated boss."},{t="h4",x="Spend mana intelligently"},{t="p",x="Efficiency cuts the mana cost of your Shots, Stings and melee abilities by 15%. Arcane Shot is optional filler. Use Rapid Fire during a useful sustained attack window. Reduce low-value casts when their mana cost creates excessive drinking time."},{t="h4",x=S[303]},{t="p",x="This build is for questing elites, dungeon bosses and boss fights, not for PvP or for farming packs. In groups, leave pack damage to others and keep your shots on your boss target."},{t="abil",names={"Sniper Shot","Aimed Shot","Arcane Shot",S[485],S[486],S[487],"Feign Death"}},{t="h3",x=S[378]},{t="p",x="Compare damage range, weapon speed, useful stats, requirements and your actual equipped item. Ranged-only bonuses do not improve melee attacks. Agility remains useful; this build also invests in Careful Aim (5/5), which turns Intellect into Attack Power, and Surefooted gives 3% hit. Do not apply a generic hit number to every encounter or attack type: check the current rules for your target and weapons before removing Surefooted."},{t="p",x=S[46]},{t="anchor",id="macros"},{t="kicker",x=S[326]},{t="h2",x=S[327]},{t="p",x=S[45]},{t="p",x=S[36]},{t="macro",n=S[208],x=S[70],code=S[154]},{t="macro",n=S[266],x=S[75],code=S[135]},{t="macro",n=S[488],x=S[67],code=S[278]},{t="macro",n=S[434],x=S[97],code=S[304]},{t="macro",n="Mend Pet",x=S[89],code=S[150]},{t="macro",n=S[225],x=S[60],code=S[102]},{t="macro",n=S[226],x=S[61],code=S[109]},{t="macro",n="Wing Clip",x=S[78],code=S[112]},{t="macro",n="Sniper Shot",x="Requires the selected Sniper Shot talent. Keeps the shot on its own bind so you decide when to use it; pet commands are omitted for Lone Wolf.",code="#showtooltip Sniper Shot\n/cast [harm,nodead] Sniper Shot"},{t="macro",n="Aimed Shot / Shift: Multi-Shot",x="Hold Shift to choose Multi-Shot; otherwise use Aimed Shot. This selects one ability, not a sequence. Check nearby enemies before choosing an attack that hits multiple targets.",code="#showtooltip\n/cast [mod:shift,harm,nodead] Multi-Shot; [harm,nodead] Aimed Shot"},{t="anchor",id="dungeons"},{t="kicker",x=S[435]},{t="h2",x=S[234]},{t="p",x=S[42]},{t="widget",w="rarity"},{t="p",s="notice",x=S[51]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[267]},{t="h2",x=S[227]},{t="p",x=S[44]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[287]},{t="h2",x=S[215]},{t="p",x=S[40]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[268]},{t="h2",x=S[201]},{t="p",x=S[41]},{t="widget",w="quest"},{t="anchor",id=S[243]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[58]}}},{id="survival",name="Survival",token="SV",title="Survival | WoW Forever Hunter Field Guide",nav={{id="overview",x=S[482]},{id="journey",x=S[315]},{id="talents",x=S[247]},{id="stats",x=S[350]},{id="combat",x=S[351]},{id="macros",x=S[352]},{id="dungeons",x=S[285]},{id="professions",x=S[316]},{id="crafting",x=S[302]},{id="questgear",x=S[276]},{id=S[243],x=S[432]}},asideNote="Researched 29 October 2026\nForever data only\n\nHover, focus or tap an item icon for its tooltip. Click to keep it open; Escape closes it.\n\nMain guide: 640 words.\nReference tables and tooltips are additional.",talentString="50000000000000000050050010000000500250230050222151",ranks={{tree="BM",name=S[339],r=5,max=5},{tree="MM",name=S[210],r=5,max=5},{tree="MM",name="Careful Aim",r=5,max=5},{tree="MM",name="Lone Wolf",r=1,max=1},{tree="SV",name=S[298],r=5,max=5},{tree="SV",name=S[615],r=2,max=2},{tree="SV",name="Survivalist",r=5,max=5},{tree="SV",name=S[668],r=2,max=2},{tree="SV",name="Surefooted",r=3,max=3},{tree="SV",name=S[590],r=5,max=5},{tree="SV",name=S[591],r=2,max=2},{tree="SV",name="Expose Prey",r=2,max=2},{tree="SV",name=S[410],r=2,max=2},{tree="SV",name=S[411],r=1,max=1},{tree="SV",name=S[534],r=5,max=5},{tree="SV",name=S[535],r=1,max=1}},order={{l1=10,l2=14,tree="SV",name=S[298],r1=1,r2=5,max=5},{l1=15,l2=19,tree="SV",name="Survivalist",r1=1,r2=5,max=5},{l1=20,l2=22,tree="SV",name="Surefooted",r1=1,r2=3,max=3},{l1=23,l2=24,tree="SV",name=S[615],r1=1,r2=2,max=2},{l1=25,l2=29,tree="SV",name=S[590],r1=1,r2=5,max=5},{l1=30,l2=30,tree="SV",name=S[411],r1=1,r2=1,max=1},{l1=31,l2=32,tree="SV",name="Expose Prey",r1=1,r2=2,max=2},{l1=33,l2=34,tree="SV",name=S[591],r1=1,r2=2,max=2},{l1=35,l2=39,tree="SV",name=S[534],r1=1,r2=5,max=5},{l1=40,l2=40,tree="SV",name=S[535],r1=1,r2=1,max=1},{l1=41,l2=42,tree="SV",name=S[668],r1=1,r2=2,max=2},{l1=43,l2=44,tree="SV",name=S[410],r1=1,r2=2,max=2},{l1=45,l2=49,tree="MM",name=S[210],r1=1,r2=5,max=5},{l1=50,l2=54,tree="MM",name="Careful Aim",r1=1,r2=5,max=5},{l1=55,l2=55,tree="MM",name="Lone Wolf",r1=1,r2=1,max=1},{l1=56,l2=60,tree="BM",name=S[339],r1=1,r2=5,max=5}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[277]},{t="h1",x="Survival",sub=S[353]},{t="p",s="lede",x="Single-target PvE Survival: a petless melee-and-trap build with Predator's Edge, Expose Prey and Lacerating Strikes, where Mongoose Bite carries the bleed damage, backed by Careful Aim, Lone Wolf and Lightning Reflexes. Not built for PvP or AoE farming."},{t="pills",list={"5 / 11 / 35 · 51 points at level 60",S[189],S[317]}},{t="anchor",id="journey"},{t="kicker",x=S[484]},{t="h2",x=S[214]},{t="p",x=S[49]},{t="p",s="level",x="1–19 · Keep ranged openings"},{t="p",x="Train a pet and use it while the melee toolkit develops; Lone Wolf is taken late. Improved Tracking reaches 5/5 by level 14 and Survivalist 5/5 by 19. Do not force melee against enemies you could safely weaken at range."},{t="p",s="level",x="20–39 · Build the melee core"},{t="p",x="Surefooted is 3/3 by 22, Savage Strikes 2/2 by 24 and Predator's Edge 5/5 by 29. Strider Kick arrives at 30, Expose Prey is 2/2 by 32, Resourcefulness 2/2 by 34 and Lightning Reflexes 5/5 by 39. Deterrence and Counterattack remain unselected. Use actual weapons and mana recovery to judge the transition to melee."},{t="p",s="level",x="40–60 · Finish Survival, then Marksmanship and Beast Mastery"},{t="p",x="Lacerating Strikes at 40 completes the 31-point core. The last twenty points finish Survival (Clever Traps and Survivalist's Discipline, 41–44), then take Marksmanship (Lethal Attacks, Careful Aim and Lone Wolf, 45–55), then Deadly Aspects (56–60). Lone Wolf at 55 is when petless play begins; a leveling pet stays useful until then."},{t="anchor",id="talents"},{t="kicker",x=S[248]},{t="h2",x="5 / 11 / 35 at level 60"},{t="p",x=S[64]},{t="widget",w="talents"},{t="h4",s="summary",x=S[286]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[233]},{t="p",x="Spend one point per level in each range. Unlisted talents stay at zero. This sequence has been checked against the calculator for totals, maximum ranks, tier gates and named prerequisites. After Lacerating Strikes at 40, the last twenty points finish the Survival tree, then take Marksmanship, then Beast Mastery."},{t="widget",w="order"},{t="p",s="notice",x="|cffffffffBuilt for single-target PvE.|r This allocation is tuned for one enemy at a time: questing elites, dungeon bosses and raid-style boss fights. It is not a PvP build and not an area-damage (AoE) farming build; Deterrence, Counterattack and the control talents are not taken, and the traps are single-target damage tools rather than pack control."},{t="p",s="notice",x="All 51 points are assigned. Savage Strikes 2/2 and Lacerating Strikes 1/1 are part of this build: Mongoose Bite applies the Lacerating Strikes bleed (40% of the hit over 21 seconds), and Deterrence and Counterattack remain at zero. Lone Wolf, Careful Aim and Lethal Attacks come from Marksmanship, and Deadly Aspects from Beast Mastery."},{t="anchor",id="stats"},{t="kicker",x=S[354]},{t="h2",x=S[264]},{t="p",x="Survival fights in melee, so your melee weapon matters as much as your bow. Agility is your main stat, with Strength adding melee attack power."},{t="h3",x=S[454]},{t="stat",i=1,b=S[367],x="melee and ranged"},{t="stat",i=2,b="Agility",x=S[244]},{t="stat",i=3,b="Stamina",x=""},{t="stat",i=4,b="Strength",x="melee attack power"},{t="p",s="small",x="Keep a decent ranged weapon for pulling, but put upgrades into your melee weapon first."},{t="h3",x="At level 60"},{t="stat",i=1,b=S[367],x=""},{t="stat",i=2,b="Hit chance",x="to 8%"},{t="stat",i=3,b=S[433],x=""},{t="stat",i=4,b="Agility",x=""},{t="stat",i=5,b=S[532],x=""},{t="p",s="small",x="Strength and Intellect are useful extras: Strength for melee attack power, Intellect for mana and Careful Aim."},{t="p",s="notice",x="Melee hit cap: 8% for special attacks against raid bosses. Expertise removes dodge at 6.5% and parry at 14% (parry only matters from the front). The level 60 list is an early estimate: the beta stopped at level 30, so expect changes once endgame gear is known. A big upgrade in a lower stat can still beat a small one in a higher stat."},{t="anchor",id="combat"},{t="kicker",x=S[265]},{t="h2",x=S[455]},{t="p",x=S[57]},{t="h4",x="Prepare the selected setup"},{t="p",x="Track the target's creature type, apply Hunter's Mark to support Expose Prey, and use Aspect of the Beast for melee: with Deadly Aspects, your melee auto attacks have a 10% chance to raise melee attack speed by 30% for 12 seconds. Lone Wolf gives 20% more damage with all attacks while you have no active pet, so go petless once you have it. Keep a ranged weapon for pulls and unsafe melee windows."},{t="h4",x="Keep melee attacks running"},{t="p",x="Use Raptor Strike and Strider Kick as available (Strider Kick deals 100% weapon damage and raises movement speed by 30% for 3 seconds), and use Mongoose Bite when enabled, including through Expose Prey, which gives attacks against a Hunter's Mark target a 10% chance to allow it for 10 seconds. Predator's Edge adds 30% critical damage to melee abilities and 50% Off Hand damage. Savage Strikes is a passive melee investment, not an extra button."},{t="h4",x="Account for the Mongoose Bite bleed"},{t="p",x="Lacerating Strikes triggers through Mongoose Bite; it is not a separate ability to cast. Its damage over time has more opportunity to contribute on durable, bleed-susceptible targets. Do not assume that delaying a ready Mongoose Bite to avoid refreshing the bleed is optimal: exact refresh behavior and level-60 priorities still need current-build testing."},{t="h4",x="Use traps and mana support"},{t="p",x="Use damaging traps for single-target damage when the target will remain in them. Clever Traps adds 30% damage to Immolation and Explosive traps, Survivalist's Discipline cuts trap cooldowns by 40%, and Resourcefulness cuts the mana cost of Trap and melee abilities by 60%. All of your traps share one 30-second cooldown, so pick the trap that fits the pull."},{t="h4",x="Stay safe and retain range"},{t="p",x="Counterattack and Deterrence are not selected. Do not include Counterattack in this rotation or seek boss attacks to trigger reactions. Switch to ranged attacks when mechanics prevent safe melee uptime. Careful Aim also turns Intellect into Attack Power, which helps every attack."},{t="h4",x=S[303]},{t="p",x="This build is for questing elites, dungeon bosses and boss fights, not for PvP or for farming packs. In groups, leave pack damage to others and keep your melee and bleed on your boss target."},{t="abil",names={"Raptor Strike","Mongoose Bite",S[411],S[485],S[486],"Aimed Shot","Arcane Shot",S[487],"Feign Death"}},{t="h3",x=S[378]},{t="p",x="Compare damage range, weapon speed, useful stats, requirements and your actual equipped item. Ranged-only bonuses do not improve melee attacks. Agility remains useful; this build also invests in Careful Aim (5/5), which turns Intellect into Attack Power for every attack, and Surefooted gives 3% hit. Do not apply a generic hit number to every encounter or attack type: check the current rules for your target and weapons before removing Surefooted."},{t="p",x=S[46]},{t="anchor",id="macros"},{t="kicker",x=S[326]},{t="h2",x=S[327]},{t="p",x=S[45]},{t="p",x=S[36]},{t="macro",n=S[208],x=S[70],code=S[154]},{t="macro",n=S[266],x=S[75],code=S[135]},{t="macro",n=S[488],x=S[67],code=S[278]},{t="macro",n=S[434],x=S[97],code=S[304]},{t="macro",n="Mend Pet",x=S[89],code=S[150]},{t="macro",n=S[225],x=S[60],code=S[102]},{t="macro",n=S[226],x=S[61],code=S[109]},{t="macro",n="Wing Clip",x=S[78],code=S[112]},{t="macro",n="Mongoose Bite and melee attack",x="Start melee attacks and use Mongoose Bite when available. The selected Lacerating Strikes talent supplies its bleed; there is no separate Lacerating Strikes cast in this macro.",code="#showtooltip Mongoose Bite\n/startattack [harm,nodead]\n/cast [harm,nodead] Mongoose Bite"},{t="macro",n=S[411],x="Requires the selected Strider Kick talent. Keep it separate from damage buttons so you can hold it for the moment you need it.",code="#showtooltip Strider Kick\n/cast [harm,nodead] Strider Kick"},{t="anchor",id="dungeons"},{t="kicker",x=S[435]},{t="h2",x=S[234]},{t="p",x=S[42]},{t="widget",w="rarity"},{t="p",s="notice",x=S[51]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[267]},{t="h2",x=S[227]},{t="p",x=S[44]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[287]},{t="h2",x=S[215]},{t="p",x=S[40]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[268]},{t="h2",x=S[201]},{t="